/** Vitals grid, nursing notes, schedule & next due time — GET /api/v1/admissions/{admission_id}/flowsheet (who may call: holders of ipd.flowsheet.view). */
export function flowsheet(admission_id: number): Promise<FlowsheetOut> {
  return api<FlowsheetOut>("GET", `/admissions/${admission_id}/flowsheet`, undefined);
}

/** Commit Flowsheet Entry: vitals — POST /api/v1/admissions/{admission_id}/flowsheet/vitals (who may call: holders of ipd.flowsheet.record). */
export function addVitals(admission_id: number, body: VitalsIn): Promise<VitalsEntryOut> {
  return api<VitalsEntryOut>("POST", `/admissions/${admission_id}/flowsheet/vitals`, body, { idempotent: true });
}

/** Visible correction entry for a vitals row — POST /api/v1/admissions/{admission_id}/flowsheet/vitals/{entry_id}/correction (who may call: holders of ipd.flowsheet.record). */
export function correctVitals(admission_id: number, entry_id: number, body: VitalsCorrectionIn): Promise<VitalsEntryOut> {
  return api<VitalsEntryOut>("POST", `/admissions/${admission_id}/flowsheet/vitals/${entry_id}/correction`, body, { idempotent: true });
}

/** Commit a nursing note — POST /api/v1/admissions/{admission_id}/flowsheet/nursing-notes (who may call: holders of ipd.flowsheet.record). */
export function addNote(admission_id: number, body: NursingNoteIn): Promise<NursingNoteOut> {
  return api<NursingNoteOut>("POST", `/admissions/${admission_id}/flowsheet/nursing-notes`, body, { idempotent: true });
}

/** Visible correction entry for a nursing note — POST /api/v1/admissions/{admission_id}/flowsheet/nursing-notes/{note_id}/correction (who may call: holders of ipd.flowsheet.record). */
export function correctNote(admission_id: number, note_id: number, body: NoteCorrectionIn): Promise<NursingNoteOut> {
  return api<NursingNoteOut>("POST", `/admissions/${admission_id}/flowsheet/nursing-notes/${note_id}/correction`, body, { idempotent: true });
}

/** Set the mandated vitals interval — PUT /api/v1/admissions/{admission_id}/flowsheet/vitals-schedule (who may call: holders of ipd.flowsheet.record or ipd.admission.request). */
export function vitalsSchedule(admission_id: number, body: VitalsScheduleIn): Promise<VitalsScheduleOut> {
  return api<VitalsScheduleOut>("PUT", `/admissions/${admission_id}/flowsheet/vitals-schedule`, body);
}

/** Operations whose surgical record needs work — GET /api/v1/ot/clinical-worklist (who may call: holders of ot.clinical.view). */
export function worklistOtClinical(query?: { mine?: boolean; days?: number; admission_id?: number | null }): Promise<SurgicalWorklistItemOut[]> {
  return api<SurgicalWorklistItemOut[]>("GET", withQuery(`/ot/clinical-worklist`, query), undefined);
}

/** The surgical record of an operation — GET /api/v1/ot/bookings/{booking_id}/surgical-record (who may call: holders of ot.clinical.view). */
export function getRecord(booking_id: number): Promise<SurgicalRecordOut> {
  return api<SurgicalRecordOut>("GET", `/ot/bookings/${booking_id}/surgical-record`, undefined);
}
